#[derive(Debug)]
enum LoginError {
    UnknownUser,
    WrongPassword,
    Locked { minutes: u32 },
}

fn login(user: &str, password: &str) -> Result<(), LoginError> {
    if user != "admin" {
        return Err(LoginError::UnknownUser);
    }
    if password == "locked" {
        return Err(LoginError::Locked { minutes: 5 });
    }
    if password != "secret" {
        return Err(LoginError::WrongPassword);
    }
    Ok(())
}

fn main() {
    println!("{:?}", login("admin", "secret"));
    println!("{:?}", login("bob", "x"));
    println!("{:?}", login("admin", "locked"));
}

use std::fmt;

#[derive(Debug)]
enum LoginError {
    UnknownUser,
    WrongPassword,
}

impl fmt::Display for LoginError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            LoginError::UnknownUser => write!(f, "no such user"),
            LoginError::WrongPassword => write!(f, "wrong password"),
        }
    }
}

impl std::error::Error for LoginError {}

fn main() {
    let errors = [LoginError::UnknownUser, LoginError::WrongPassword];
    for e in errors {
        println!("Login failed: {e}");
    }
}

use std::num::ParseIntError;

#[derive(Debug)]
enum ConfigError {
    BadNumber(ParseIntError),
    OutOfRange(i32),
}

impl From<ParseIntError> for ConfigError {
    fn from(e: ParseIntError) -> Self {
        ConfigError::BadNumber(e)
    }
}

fn read_volume(s: &str) -> Result<i32, ConfigError> {
    let v: i32 = s.parse()?;   // ParseIntError becomes ConfigError
    if !(0..=100).contains(&v) {
        return Err(ConfigError::OutOfRange(v));
    }
    Ok(v)
}

fn main() {
    println!("{:?}", read_volume("70"));
    println!("{:?}", read_volume("150"));
    println!("{}", matches!(read_volume("loud"), Err(ConfigError::BadNumber(_))));
}

